lib/common/env.sh.text:
#!/bin/bash
# Environment: relay_env loads config/defaults.env and then config/partners/<partner>.env.
relay_env() { set -a; . config/defaults.env; [ -n "${1:-}" ] && [ -f "config/partners/$1.env" ] && . "config/partners/$1.env"; set +a; }

lib/common/log.sh.text:
#!/bin/bash
# Logging: relay_log <level> <message...>. Levels: debug info warn error. Format from ADR-0006.
relay_log() { local level="$1"; shift; printf '%s %s %s\n' "$(date -u +%Y-%m-%dT%H:%M:%SZ)" "$level" "$*" >&2; }

lib/common/money.sh.text:
#!/bin/bash
# Money in integer cents (ADR-0008). cents_to_text 12345 -> 123.45
cents_to_text() { printf '%d.%02d\n' $(( $1 / 100 )) $(( $1 % 100 )); }
fee_for() { echo $(( $1 * ${RELAY_LEDGER_FEE_BP:-150} / 10000 )); }

lib/delivery/http.sh.text:
#!/bin/bash
# HTTP helpers for webhook delivery. relay_post <url> <body-file> prints the status code.
relay_post() {
  local url="$1" body="$2"
  ${RELAY_HTTP:-curl} -s -o /dev/null -w '%{http_code}\n' -X POST -H 'Content-Type: application/json' --data-binary "@$body" "$url"
}
relay_sign() { printf '%s' "$1" | openssl dgst -sha256 -hmac "${RELAY_WEBHOOK_SECRET:-unset}" 2>/dev/null | sed 's/^.* //'; }

lib/delivery/retry.sh.text:
#!/bin/bash
# Retry schedule for webhook delivery (ADR-0009).
# Attempts: RELAY_ATTEMPTS (default 4). Wait before attempt i+1 is 3^i s (3, 9, 27, ...).
RELAY_ATTEMPTS_DEFAULT=4
RELAY_WAIT_BASE=3
RELAY_WAIT_FIRST=3
relay_attempts() { echo "${RELAY_ATTEMPTS:-$RELAY_ATTEMPTS_DEFAULT}"; }
relay_wait_for() { local i="$1" w="$RELAY_WAIT_FIRST"; while [ "$i" -gt 1 ]; do w=$(( w * RELAY_WAIT_BASE )); i=$(( i - 1 )); done; echo "$w"; }
relay_waits() { local n i=1 out=""; n=$(relay_attempts); while [ "$i" -lt "$n" ]; do out="${out:+$out,}$(relay_wait_for "$i")"; i=$(( i + 1 )); done; echo "$out"; }

