#!/bin/bash
# deliver: a succeeding command is delivered on the first attempt; a failing one exits 1.
# RLY-731: schedule follows ADR-0009 (4 attempts, waits 3^i) and the key RELAY_ATTEMPTS.
fail=0
[ "$(RELAY_SLEEP=: bash bin/deliver true | tail -1)" = delivered ] || { echo "deliver true"; fail=1; }
RELAY_SLEEP=: bash bin/deliver false >/dev/null; [ $? = 1 ] || { echo "deliver false"; fail=1; }
[ "$(env -u RELAY_ATTEMPTS -u RELAY_RETRY_MAX bash bin/deliver --plan)" = "attempts=4 waits=3,9,27" ] || { echo "default plan"; fail=1; }
[ "$(RELAY_ATTEMPTS=6 bash bin/deliver --plan)" = "attempts=6 waits=3,9,27,81,243" ] || { echo "RELAY_ATTEMPTS plan"; fail=1; }
[ "$(RELAY_RETRY_MAX=9 env -u RELAY_ATTEMPTS bash bin/deliver --plan)" = "attempts=4 waits=3,9,27" ] || { echo "RELAY_RETRY_MAX must be ignored"; fail=1; }
[ "$(RELAY_SLEEP=echo bash bin/deliver false | grep -c '^attempt ')" = 4 ] || { echo "4 attempts run"; fail=1; }
