    *) echo "upload: unknown mode $mode" >&2; return 2 ;;
  esac
  local n=$(( (${#id} * 6 + 2) % limit ))
  if [ "$n" -eq 0 ]; then
    printf '%s %s: empty\n' "upload" "$id"
    return 1
  fi
  printf '%s %s: %d of %d (%s)\n' "upload" "$id" "$n" "$limit" "$mode"
}

tests/deliver_test.sh.text:
#!/bin/bash
# deliver: a succeeding command is delivered on the first attempt; a failing one exits 1.
fail=0
[ "$(RELAY_SLEEP=: bash bin/deliver true | tail -1)" = delivered ] || { echo "deliver true"; fail=1; }
RELAY_SLEEP=: bash bin/deliver false >/dev/null; [ $? = 1 ] || { echo "deliver false"; fail=1; }
# ADR-0009: 4 attempts, waits 3^i (3, 9, 27 s); the runbook key is RELAY_ATTEMPTS.
[ "$(bash bin/deliver --plan)" = "attempts=4 waits=3,9,27" ] || { echo "plan default"; fail=1; }
[ "$(RELAY_ATTEMPTS=6 bash bin/deliver --plan)" = "attempts=6 waits=3,9,27,81,243" ] || { echo "plan RELAY_ATTEMPTS=6"; fail=1; }
# RELAY_RETRY_MAX is no longer read (CHANGELOG 1.9.0).
[ "$(RELAY_RETRY_MAX=9 bash bin/deliver --plan)" = "attempts=4 waits=3,9,27" ] || { echo "RELAY_RETRY_MAX must be ignored"; fail=1; }
out=$(RELAY_SLEEP=echo bash bin/deliver false)
[ "$(echo "$out" | grep -c '^attempt ')" = 4 ] || { echo "4 attempts run"; fail=1; }
[ "$(echo "$out" | grep -E '^(3|9|27|81)$' | tr '\n' ' ')" = "3 9 27 " ] || { echo "sleep args"; fail=1; }
exit $fail

