tests/deliver_test.sh.text:
#!/bin/bash
# deliver: a succeeding command is delivered on the first attempt; a failing one exits 1.
# Retry policy follows ADR-0009: 4 attempts, waits 3^i s (3, 9, 27); count set by RELAY_ATTEMPTS.
fail=0
[ "$(RELAY_SLEEP=: bash bin/deliver true | tail -1)" = delivered ] || { echo "deliver true"; fail=1; }
RELAY_SLEEP=: bash bin/deliver false >/dev/null; [ $? = 1 ] || { echo "deliver false"; fail=1; }
[ "$(bash bin/deliver --plan)" = "attempts=4 waits=3,9,27" ] || { echo "default plan"; fail=1; }
[ "$(RELAY_ATTEMPTS=6 bash bin/deliver --plan)" = "attempts=6 waits=3,9,27,81,243" ] || { echo "RELAY_ATTEMPTS=6 plan"; fail=1; }
[ "$(RELAY_RETRY_MAX=9 bash bin/deliver --plan)" = "attempts=4 waits=3,9,27" ] || { echo "RELAY_RETRY_MAX must be ignored"; fail=1; }
[ "$(RELAY_SLEEP=echo bash bin/deliver false | grep -c '^attempt ')" = 4 ] || { echo "4 attempts run"; fail=1; }
[ "$(RELAY_SLEEP=echo bash bin/deliver false | grep '^wait ' | tr '\n' ' ')" = "wait 3s wait 9s wait 27s " ] || { echo "waits run"; fail=1; }
exit $fail

